import React, { useState, useEffect } from 'react';
import styled from 'styled-components';

const ChatbotContainer = styled.div`
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 400px;
  max-height: 600px;
  border: 1px solid #ddd;
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  background: #fff;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 1000;
`;

const ChatbotHeader = styled.div`
  background: #007bff;
  color: white;
  padding: 10px;
  text-align: center;
  font-weight: bold;
  cursor: pointer;
`;

const ChatWindow = styled.div`
  flex: 1;
  padding: 10px;
  overflow-y: auto;
  font-size: 0.9rem;
  color: #333;
`;

const ChatInputContainer = styled.div`
  display: flex;
  padding: 10px;
  border-top: 1px solid #ddd;
`;

const ChatInput = styled.input`
  flex: 1;
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 5px;
  font-size: 1rem;
`;

const SendButton = styled.button`
  padding: 8px 15px;
  margin-left: 10px;
  border: none;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

const Chatbot = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isOpen, setIsOpen] = useState(true);
  const [isFirstGreeting, setIsFirstGreeting] = useState(true);

  const knowledgeBase = {
    hello: `Hi! I'm your triathlon assistant. Here's what I can help you with:
- Beginner tips: Type "beginner".
- Training advice: Type "training".
- Gear recommendations: Type "gear".
- Race day tips: Type "race day".
- Nutrition guidance: Type "nutrition".
- Open water swimming: Type "swimming".
- Signing up for races: Type "signup".
- Advanced strategies: Type "advanced".
- FAQs: Type "faq".
Need help exploring? Type "help".`,
    help: `
Here are topics I can assist you with:
- **Beginner Advice**: Basic steps to get started. Type "beginner".
- **Training Plans**: Weekly schedules, brick workouts, and more. Type "training".
- **Gear Suggestions**: Beginner, intermediate, and advanced gear. Type "gear".
- **Race Day Preparation**: Tips and checklists. Type "race day".
- **Nutrition Guidance**: Fueling for endurance events. Type "nutrition".
- **Open Water Swimming**: Techniques and tips. Type "swimming".
- **Advanced Strategies**: Competitive tips for experienced triathletes. Type "advanced".
- **Sign-Up Process**: How to register for events. Type "signup".
- **FAQs**: Common questions about triathlons. Type "faq".
Let me know what you’d like to learn about!`,
    beginner: `
Starting as a beginner? Here's how to get started:
1. **Start Small**:
   - Choose a sprint triathlon (shorter distances).
   - Swim: 750m, Bike: 20km, Run: 5km.
2. **Essential Gear**:
   - Road bike (entry-level is fine).
   - Helmet, goggles, running shoes, and a tri-suit.
3. **Training Basics**:
   - Swim 2x/week: Practice breathing and endurance.
   - Bike 2x/week: Focus on cadence and distance.
   - Run 2x/week: Alternate between sprints and long runs.
4. **Transition Practice**:
   - Swim-to-bike (T1) and bike-to-run (T2).
   - Lay out your gear for quick changes.
5. **Set a Goal**:
   - Register for a local sprint triathlon 3-6 months from now.
`,
    training: `
Training for a triathlon? Here’s a guide:
1. **Weekly Schedule**:
   - 2x Swimming: Work on technique and endurance.
   - 2x Cycling: Build speed and distance.
   - 2x Running: Combine interval training and endurance runs.
   - 1x Rest Day: Recovery is essential.
2. **Brick Workouts**:
   - Combine two disciplines in one session (e.g., bike + run).
3. **Progression**:
   - Increase distances weekly by no more than 10%.
4. **Tracking Tools**:
   - Apps like Strava or Garmin for progress tracking.
5. **Tips**:
   - Include strength training to prevent injuries.
   - Alternate between hard and easy weeks to avoid burnout.
`,
    gear: `
Gear recommendations for triathlons:
1. **Beginner Gear**:
   - Road bike (e.g., Giant Contend, Trek Domane AL).
   - Running shoes: Brooks Ghost or Asics Gel.
   - Swim goggles: TYR or Speedo.
   - Basic tri-suit: Orca or Zone3 entry-level.
2. **Intermediate Gear**:
   - Carbon-frame bike with aero bars.
   - Wetsuit for buoyancy and speed: Orca S7 or Zone3 Aspire.
   - GPS watch: Garmin Forerunner 745.
3. **Advanced Gear**:
   - Triathlon-specific bike: Cervelo P-Series or Trek Speed Concept.
   - Carbon-plated running shoes for speed: Nike Vaporfly or Hoka Carbon X.
   - Power meter for cycling efficiency.
4. **Accessories**:
   - Aero helmet, hydration packs, and clipless pedals.
`,
    "race day": `
Race day preparation:
1. **Checklist**:
   - Tri-suit, bike, helmet, goggles, running shoes, hydration, and nutrition.
   - Transition gear: Towels, socks, and an extra layer for cold weather.
2. **Morning Routine**:
   - Arrive early to set up your transition area.
   - Warm up lightly (e.g., jogging or stretching).
3. **During the Race**:
   - Pace yourself. Start slow and maintain energy.
   - Follow your nutrition plan: gels and hydration every 30-45 minutes.
   - Enjoy the experience and focus on crossing the finish line.
`,
    nutrition: `
Triathlon nutrition:
1. **Before the Race**:
   - Carbo-load 1-2 days prior to build glycogen stores.
   - Eat a light, carb-rich breakfast (e.g., oatmeal with banana).
2. **During the Race**:
   - Consume energy gels or bars every 30-45 minutes.
   - Stay hydrated with water or electrolyte drinks.
3. **Recovery**:
   - Eat a protein-carb meal within 30 minutes post-race.
   - Drink plenty of fluids to replenish lost electrolytes.
`,
    swimming: `
Open water swimming tips:
1. **Practice**:
   - Train in lakes, rivers, or the sea to adapt.
   - Work on sighting to swim in a straight line.
2. **Gear**:
   - Wetsuit for buoyancy (mandatory in cold water).
   - Goggles with anti-fog and UV protection.
3. **Techniques**:
   - Controlled breathing: Exhale fully underwater.
   - Drafting: Swim behind others to save energy.
   - Bilateral breathing for balance.
`,
    advanced: `
Advanced strategies for experienced triathletes:
1. **Gear Upgrades**:
   - Invest in a high-end tri-bike and carbon-plated running shoes.
   - Use a power meter to optimize cycling output.
2. **Training Refinements**:
   - Incorporate interval training for speed.
   - Train with a coach for improved technique.
3. **Race Tactics**:
   - Practice negative splits (faster in the second half).
   - Study the course to prepare for hills and turns.
   - Use aero-position during cycling for reduced drag.
`,
    signup: `
How to sign up for a triathlon:
1. Research races on websites like **Ironman.com** or local triathlon clubs.
2. Choose a race based on distance and location.
3. Register early to secure your spot.
4. Review the race’s rules, distances, and cut-off times.
5. Prepare your gear and start training!
`,
    faq: `
Frequently Asked Questions:
1. **Do I need an expensive bike?**
   - No, an entry-level road bike works fine for beginners.
2. **How long does training take?**
   - For a sprint triathlon: 8-12 weeks of consistent training.
3. **What’s a transition?**
   - The switch between disciplines (e.g., swim to bike).
4. **What if I can’t swim well?**
   - Start with swim lessons and focus on building endurance.
`,
  };

  useEffect(() => {
    if (isFirstGreeting) {
      const greeting = {
        sender: 'bot',
        text: `Hi! I’m your triathlon assistant. Type "help" to see what I can do.`,
      };
      setMessages([greeting]);
      setIsFirstGreeting(false);
    }
  }, [isFirstGreeting]);

  const handleSendMessage = () => {
    if (input.trim() === '') return;

    const userMessage = { sender: 'user', text: input };
    let botResponse;

    const lowerInput = input.toLowerCase();
    if (knowledgeBase[lowerInput]) {
      botResponse = knowledgeBase[lowerInput];
    } else {
      botResponse = `I'm not sure about that. Try asking for "help" to see what I can assist with!`;
    }

    const botMessage = { sender: 'bot', text: botResponse };
    setMessages([...messages, userMessage, botMessage]);
    setInput('');
  };

  const toggleChatbot = () => {
    setIsOpen(!isOpen);
  };

  return (
    <ChatbotContainer>
      <ChatbotHeader onClick={toggleChatbot}>
        {isOpen ? 'Triathlon Assistant' : 'Open Chat'}
      </ChatbotHeader>
      {isOpen && (
        <>
          <ChatWindow>
            {messages.map((msg, index) => (
              <p
                key={index}
                style={{
                  textAlign: msg.sender === 'user' ? 'right' : 'left',
                  margin: '5px 0',
                }}
              >
                <strong>{msg.sender === 'user' ? 'You: ' : 'Bot: '}</strong>
                {msg.text}
              </p>
            ))}
          </ChatWindow>
          <ChatInputContainer>
            <ChatInput
              type="text"
              placeholder="Ask me about triathlons!"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            />
            <SendButton onClick={handleSendMessage}>Send</SendButton>
          </ChatInputContainer>
        </>
      )}
    </ChatbotContainer>
  );
};

export default Chatbot;
